candidates.raw:
size_t i;
adcs_vec3_t axis, term;

if ((wheels == NULL) || (momentum_body_nms == NULL)) {
    if (momentum_body_nms != NULL) {
        momentum_body_nms->x = 0.0;
        momentum_body_nms->y = 0.0;
        momentum_body_nms->z = 0.0;
    }
    return ADCS_E_NULL;
}

momentum_body_nms->x = 0.0;
momentum_body_nms->y = 0.0;
momentum_body_nms->z = 0.0;

if ((count < 1U) || (count > 16U)) {
    return ADCS_E_RANGE;
}

for (i = 0; i < count; i++) {
    if ((!adcs_is_finite_vec3(&wheels[i].axis_body)) ||
        (!isfinite(wheels[i].inertia_kg_m2)) ||
        (!isfinite(wheels[i].speed_rad_s)) ||
        (wheels[i].inertia_kg_m2 <= 0.0)) {
        return ADCS_E_RANGE;
    }
    if (adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis) != ADCS_OK) {
        return ADCS_E_RANGE;
    }
}

for (i = 0; i < count; i++) {
    double h_scalar;
    (void)adcs_vec3_normalize(&wheels[i].axis_body, ADCS_EPS_NORM, &axis);
    h_scalar = wheels[i].inertia_kg_m2 * wheels[i].speed_rad_s;
    term = adcs_vec3_scale(&axis, h_scalar);
    *momentum_body_nms = adcs_vec3_add(momentum_body_nms, &term);
}

return ADCS_OK;
}

